    question: "钱锺书的代表作品有长篇小说《围城》、短篇小说集《人·兽·鬼》、诗话《谈艺录》、学术著作《管锥编》和散文随笔集《____》等。《围城》是钱锺书唯一的一部长篇小说，小说以留学归来的方鸿渐为中心人物，描写全面抗战爆发前后从上海到湖南后方的一些知识分子的生活。这是一部讽刺小说，以含蓄的笔法描写人物光彩体面外表下的矛盾因素，对中国知识界的人物和现象进行讽刺，被誉为“新《儒林外史》”。“婚姻是一座围城，城外的人想进去，城里的人想出来”这句诠释婚姻的经典语录出自《围城》。",
