    explanation: "\"桐城派\"是清代文坛最大的散文流派，由方苞开创，其后刘大櫆、姚鼐等又进一步发展，方苞、刘大櫆、姚鼐被尊为\"桐城派三祖\"。\"桐城派\"主张学习《左传》《史记》等先秦、两汉散文和唐宋古文家韩愈、欧阳修等人的作品，讲究\"义法\"，提倡\"义理\"\"考据\"\"词章\"三者并重，要求语言雅洁，反对俚俗。"
