    options: ["汤显祖《牡丹亭》","王实甫《西厢记》","曾朴《孽海花》","关汉卿《窦娥冤》"],
    answer: "C",
    explanation: "曾朴的《孽海花》是\"晚清四大谴责小说\"之一。谴责小说是中国旧小说的一种，指清末戊戌变法运动失败后大量出现的以暴露社会黑暗、指摘政治腐败为主要内容的小说。其代表作品有李宝嘉的《官场现形记》、吴沃尧的《二十年目睹之怪现状》、刘鹗的《老残游记》、曾朴的《孽海花》，合称\"晚清四大谴责小说\"。"
