    question: "下列关于古代称谓的说法错误的是（　）",
    options: ["\"阁下\"是介绍自己时的谦辞","\"足下\"可用于下级对上级或同辈之间尊敬的称呼","\"内子\"用于丈夫对别人称自己的妻子","\"舍\"用于谦称自己的家或者自己的卑幼亲属"],
    answer: "A",
