    answer: "A",
    explanation: "鲁迅是我国伟大的文学家、思想家、革命家。1902年赴日本留学，初学医，后弃医从文，以笔代戈，战斗一生，为唤醒沉睡的民众不遗余力，其精神被誉为\"中华民族魂\"。"
