    answer: "C",
    explanation: "杜甫是我国古代最伟大的现实主义诗人，各体皆长，五古、七律成就尤高。其五古措辞质朴厚实，格调沉郁顿挫；其七律语句精练且严守声律，一丝不苟。杜甫终以沉郁顿挫的风格、千锤百炼的语言、精细老成的诗律，被后世推崇为\"诗圣\"。"
