    question: "下面哪句诗能体现出作者离开家的时间最长（）",
    options: ["人归落雁后，思发在花前","朝辞白帝彩云间，千里江陵一日还","昨夜闲潭梦落花，可怜春半不还家","少小离家老大回，乡音无改鬓毛衰"],
    answer: "D",
